=head2 Google::Devtools::Testing::V1::TestExecution::TestMatrix

TestMatrix captures all details about a test. It contains the environment
configuration, test specification, test executions and overall state and
outcome.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->test_matrix_id() >> / C<< $msg->test_matrix_id($value) >>

Type: C<String>

Output only. Unique id set by the service.

=item * C<< $msg->project_id() >> / C<< $msg->project_id($value) >>

Type: C<String>

The cloud project that owns the test matrix.

=item * C<< $msg->client_info() >> / C<< $msg->client_info($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::ClientInfo>)

Information about the client which invoked the test.

=item * C<< $msg->test_specification() >> / C<< $msg->test_specification($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::TestSpecification>)

Required. How to run the test.

=item * C<< $msg->environment_matrix() >> / C<< $msg->environment_matrix($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::EnvironmentMatrix>)

Required. The devices the tests are being executed on.

=item * C<< $msg->test_executions() >> / C<< $msg->test_executions($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::TestExecution>)

Output only. The list of test executions that the service creates for
this matrix.

=item * C<< $msg->result_storage() >> / C<< $msg->result_storage($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::ResultStorage>)

Required. Where the results for the matrix are written.

=item * C<< $msg->state() >> / C<< $msg->state($value) >>

Type: C<Enum> (L<Google::Devtools::Testing::V1::TestState>)

Output only. Indicates the current progress of the test matrix.

=item * C<< $msg->timestamp() >> / C<< $msg->timestamp($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. The time this test matrix was initially created.

=item * C<< $msg->invalid_matrix_details() >> / C<< $msg->invalid_matrix_details($value) >>

Type: C<Enum> (L<Google::Devtools::Testing::V1::InvalidMatrixDetails>)

Output only. Describes why the matrix is considered invalid.
Only useful for matrices in the INVALID state.

=item * C<< $msg->extended_invalid_matrix_details() >> / C<< $msg->extended_invalid_matrix_details($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::MatrixErrorDetail>)

Output only. Details about why a matrix was deemed invalid.
If multiple checks can be safely performed, they will be reported but no
assumptions should be made about the length of this list.

=item * C<< $msg->flaky_test_attempts() >> / C<< $msg->flaky_test_attempts($value) >>

Type: C<Int32>

The number of times a TestExecution should be re-attempted if one or more
of its test cases fail for any reason.
The maximum number of reruns allowed is 10.

Default is 0, which implies no reruns.

=item * C<< $msg->outcome_summary() >> / C<< $msg->outcome_summary($value) >>

Type: C<Enum> (L<Google::Devtools::Testing::V1::OutcomeSummary>)

Output Only. The overall outcome of the test.
Only set when the test matrix state is FINISHED.

=item * C<< $msg->fail_fast() >> / C<< $msg->fail_fast($value) >>

Type: C<Bool>

If true, only a single attempt at most will be made to run each
execution/shard in the matrix. Flaky test attempts are not affected.

Normally, 2 or more attempts are made if a potential infrastructure issue
is detected.

This feature is for latency sensitive workloads. The incidence of
execution failures may be significantly greater for fail-fast matrices
and support is more limited because of that expectation.

=back

=head2 Google::Devtools::Testing::V1::TestExecution::MatrixErrorDetail

Describes a single error or issue with a matrix.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->reason() >> / C<< $msg->reason($value) >>

Type: C<String>

Output only. The reason for the error. This is a constant value in
UPPER_SNAKE_CASE that identifies the cause of the error.

=item * C<< $msg->message() >> / C<< $msg->message($value) >>

Type: C<String>

Output only. A human-readable message about how the error in the
TestMatrix. Expands on the `reason` field with additional details and
possible options to fix the issue.

=back

=head2 Google::Devtools::Testing::V1::TestExecution::TestExecution

A single test executed in a single environment.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->id() >> / C<< $msg->id($value) >>

Type: C<String>

Output only. Unique id set by the service.

=item * C<< $msg->matrix_id() >> / C<< $msg->matrix_id($value) >>

Type: C<String>

Output only. Id of the containing TestMatrix.

=item * C<< $msg->project_id() >> / C<< $msg->project_id($value) >>

Type: C<String>

Output only. The cloud project that owns the test execution.

=item * C<< $msg->test_specification() >> / C<< $msg->test_specification($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::TestSpecification>)

Output only. How to run the test.

=item * C<< $msg->shard() >> / C<< $msg->shard($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::Shard>)

Output only. Details about the shard.

=item * C<< $msg->environment() >> / C<< $msg->environment($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::Environment>)

Output only. How the host machine(s) are configured.

=item * C<< $msg->state() >> / C<< $msg->state($value) >>

Type: C<Enum> (L<Google::Devtools::Testing::V1::TestState>)

Output only. Indicates the current progress of the test execution
(e.g., FINISHED).

=item * C<< $msg->tool_results_step() >> / C<< $msg->tool_results_step($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::ToolResultsStep>)

Output only. Where the results for this execution are written.

=item * C<< $msg->timestamp() >> / C<< $msg->timestamp($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. The time this test execution was initially created.

=item * C<< $msg->test_details() >> / C<< $msg->test_details($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::TestDetails>)

Output only. Additional details about the running test.

=back

=head2 Google::Devtools::Testing::V1::TestExecution::TestSpecification

A description of how to run the test.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->test_timeout() >> / C<< $msg->test_timeout($value) >>

Type: C<Message> (L<Google::Protobuf::Duration::Duration>)

Max time a test execution is allowed to run before it is
automatically cancelled.
The default value is 5 min.

=item * C<< $msg->test_setup() >> / C<< $msg->test_setup($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::TestSetup>)

Test setup requirements for Android e.g. files to install, bootstrap
scripts.

=item * C<< $msg->ios_test_setup() >> / C<< $msg->ios_test_setup($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::IosTestSetup>)

Test setup requirements for iOS.

=item * C<< $msg->android_instrumentation_test() >> / C<< $msg->android_instrumentation_test($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::AndroidInstrumentationTest>)

An Android instrumentation test.

=item * C<< $msg->android_robo_test() >> / C<< $msg->android_robo_test($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::AndroidRoboTest>)

An Android robo test.

=item * C<< $msg->android_test_loop() >> / C<< $msg->android_test_loop($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::AndroidTestLoop>)

An Android Application with a Test Loop.

=item * C<< $msg->ios_xc_test() >> / C<< $msg->ios_xc_test($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::IosXcTest>)

An iOS XCTest, via an .xctestrun file.

=item * C<< $msg->ios_test_loop() >> / C<< $msg->ios_test_loop($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::IosTestLoop>)

An iOS application with a test loop.

=item * C<< $msg->ios_robo_test() >> / C<< $msg->ios_robo_test($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::IosRoboTest>)

An iOS Robo test.

=item * C<< $msg->disable_video_recording() >> / C<< $msg->disable_video_recording($value) >>

Type: C<Bool>

Disables video recording. May reduce test latency.

=item * C<< $msg->disable_performance_metrics() >> / C<< $msg->disable_performance_metrics($value) >>

Type: C<Bool>

Disables performance metrics recording. May reduce test latency.

=back

=head2 Google::Devtools::Testing::V1::TestExecution::SystraceSetup

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->duration_seconds() >> / C<< $msg->duration_seconds($value) >>

Type: C<Int32>

Systrace duration in seconds.
Should be between 1 and 30 seconds. 0 disables systrace.

=back

=head2 Google::Devtools::Testing::V1::TestExecution::TestSetup

A description of how to set up the Android device prior to running the test.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->files_to_push() >> / C<< $msg->files_to_push($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::DeviceFile>)

List of files to push to the device before starting the test.

=item * C<< $msg->directories_to_pull() >> / C<< $msg->directories_to_pull($value) >>

Type: C<String>

List of directories on the device to upload to GCS at the end of the test;
they must be absolute paths under /sdcard, /storage or /data/local/tmp.
Path names are restricted to characters a-z A-Z 0-9 _ - . + and /

Note: The paths /sdcard and /data will be made available and treated as
implicit path substitutions. E.g. if /sdcard on a particular device does
not map to external storage, the system will replace it with the external
storage path prefix for that device.

=item * C<< $msg->initial_setup_apks() >> / C<< $msg->initial_setup_apks($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::Apk>)

Optional. Initial setup APKs to install before the app under test is
installed. Currently capped at 100.

=item * C<< $msg->additional_apks() >> / C<< $msg->additional_apks($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::Apk>)

APKs to install in addition to those being directly tested. These will be
installed after the app under test.
Currently capped at 100.

=item * C<< $msg->account() >> / C<< $msg->account($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::Account>)

The device will be logged in on this account for the duration of the test.

=item * C<< $msg->network_profile() >> / C<< $msg->network_profile($value) >>

Type: C<String>

The network traffic profile used for running the test.
Available network profiles can be queried by using the
NETWORK_CONFIGURATION environment type when calling
TestEnvironmentDiscoveryService.GetTestEnvironmentCatalog.

=item * C<< $msg->environment_variables() >> / C<< $msg->environment_variables($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::EnvironmentVariable>)

Environment variables to set for the test (only applicable for
instrumentation tests).

=item * C<< $msg->systrace() >> / C<< $msg->systrace($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::SystraceSetup>)

Systrace configuration for the run.
Deprecated: Systrace used Python 2 which was sunsetted on 2020-01-01.
Systrace is no longer supported in the Cloud Testing API, and no Systrace
file will be provided in the results.

=item * C<< $msg->dont_autogrant_permissions() >> / C<< $msg->dont_autogrant_permissions($value) >>

Type: C<Bool>

Whether to prevent all runtime permissions to be granted at app install

=back

=head2 Google::Devtools::Testing::V1::TestExecution::IosTestSetup

A description of how to set up an iOS device prior to running the test.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->network_profile() >> / C<< $msg->network_profile($value) >>

Type: C<String>

The network traffic profile used for running the test.
Available network profiles can be queried by using the
NETWORK_CONFIGURATION environment type when calling
TestEnvironmentDiscoveryService.GetTestEnvironmentCatalog.

=item * C<< $msg->additional_ipas() >> / C<< $msg->additional_ipas($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::FileReference>)

iOS apps to install in addition to those being directly tested.

=item * C<< $msg->push_files() >> / C<< $msg->push_files($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::IosDeviceFile>)

List of files to push to the device before starting the test.

=item * C<< $msg->pull_directories() >> / C<< $msg->pull_directories($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::IosDeviceFile>)

List of directories on the device to upload to Cloud Storage at the end of
the test.

Directories should either be in a shared directory (such as
/private/var/mobile/Media) or within an accessible directory inside the
app's filesystem (such as /Documents) by specifying the bundle ID.

=back

=head2 Google::Devtools::Testing::V1::TestExecution::EnvironmentVariable

A key-value pair passed as an environment variable to the test.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->key() >> / C<< $msg->key($value) >>

Type: C<String>

Key for the environment variable.

=item * C<< $msg->value() >> / C<< $msg->value($value) >>

Type: C<String>

Value for the environment variable.

=back

=head2 Google::Devtools::Testing::V1::TestExecution::Account

Identifies an account and how to log into it.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->google_auto() >> / C<< $msg->google_auto($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::GoogleAuto>)

An automatic google login account.

=back

=head2 Google::Devtools::Testing::V1::TestExecution::GoogleAuto

Enables automatic Google account login.
If set, the service automatically generates a Google test account and adds
it to the device, before executing the test. Note that test accounts might be
reused.
Many applications show their full set of functionalities when an account is
present on the device. Logging into the device with these generated accounts
allows testing more functionalities.

Inherits from L<Protobuf::Message>.

=head2 Google::Devtools::Testing::V1::TestExecution::Apk

An Android package file to install.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->location() >> / C<< $msg->location($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::FileReference>)

The path to an APK to be installed on the device before the test begins.

=item * C<< $msg->package_name() >> / C<< $msg->package_name($value) >>

Type: C<String>

The java package for the APK to be installed.
Value is determined by examining the application's manifest.

=back

=head2 Google::Devtools::Testing::V1::TestExecution::AppBundle

An Android App Bundle file format, containing a BundleConfig.pb file,
a base module directory, zero or more dynamic feature module directories.
<p>See https://developer.android.com/guide/app-bundle/build for guidance on
building App Bundles.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->bundle_location() >> / C<< $msg->bundle_location($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::FileReference>)

.aab file representing the app bundle under test.

=back

=head2 Google::Devtools::Testing::V1::TestExecution::DeviceFile

A single device file description.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->obb_file() >> / C<< $msg->obb_file($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::ObbFile>)

A reference to an opaque binary blob file.

=item * C<< $msg->regular_file() >> / C<< $msg->regular_file($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::RegularFile>)

A reference to a regular file.

=back

=head2 Google::Devtools::Testing::V1::TestExecution::ObbFile

An opaque binary blob file to install on the device before the test starts.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->obb_file_name() >> / C<< $msg->obb_file_name($value) >>

Type: C<String>

Required. OBB file name which must conform to the format as specified by
Android
e.g. [main|patch].0300110.com.example.android.obb
which will be installed into
  \<shared-storage\>/Android/obb/\<package-name\>/
on the device.

=item * C<< $msg->obb() >> / C<< $msg->obb($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::FileReference>)

Required. Opaque Binary Blob (OBB) file(s) to install on the device.

=back

=head2 Google::Devtools::Testing::V1::TestExecution::RegularFile

A file or directory to install on the device before the test starts.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->content() >> / C<< $msg->content($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::FileReference>)

Required. The source file.

=item * C<< $msg->device_path() >> / C<< $msg->device_path($value) >>

Type: C<String>

Required. Where to put the content on the device. Must be an absolute,
allowlisted path. If the file exists, it will be replaced.
The following device-side directories and any of their subdirectories are
allowlisted:
<p>${EXTERNAL_STORAGE}, /sdcard, or /storage</p>
<p>${ANDROID_DATA}/local/tmp, or /data/local/tmp</p>
<p>Specifying a path outside of these directory trees is invalid.

<p> The paths /sdcard and /data will be made available and treated as
implicit path substitutions. E.g. if /sdcard on a particular device does
not map to external storage, the system will replace it with the external
storage path prefix for that device and copy the file there.

<p> It is strongly advised to use the <a href=
"http://developer.android.com/reference/android/os/Environment.html">
Environment API</a> in app and test code to access files on the device in a
portable way.

=back

=head2 Google::Devtools::Testing::V1::TestExecution::IosDeviceFile

A file or directory to install on the device before the test starts.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->content() >> / C<< $msg->content($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::FileReference>)

The source file

=item * C<< $msg->bundle_id() >> / C<< $msg->bundle_id($value) >>

Type: C<String>

The bundle id of the app where this file lives.

iOS apps sandbox their own filesystem, so app files must specify which app
installed on the device.

=item * C<< $msg->device_path() >> / C<< $msg->device_path($value) >>

Type: C<String>

Location of the file on the device, inside the app's sandboxed filesystem

=back

=head2 Google::Devtools::Testing::V1::TestExecution::AndroidTestLoop

A test of an Android Application with a Test Loop.
The intent \<intent-name\> will be implicitly added, since Games is the only
user of this api, for the time being.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->app_apk() >> / C<< $msg->app_apk($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::FileReference>)

The APK for the application under test.

=item * C<< $msg->app_bundle() >> / C<< $msg->app_bundle($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::AppBundle>)

A multi-apk app bundle for the application under test.

=item * C<< $msg->app_package_id() >> / C<< $msg->app_package_id($value) >>

Type: C<String>

The java package for the application under test.
The default is determined by examining the application's manifest.

=item * C<< $msg->scenarios() >> / C<< $msg->scenarios($value) >>

Type: C<Int32>

The list of scenarios that should be run during the test.
The default is all test loops, derived from the application's
manifest.

=item * C<< $msg->scenario_labels() >> / C<< $msg->scenario_labels($value) >>

Type: C<String>

The list of scenario labels that should be run during the test.
The scenario labels should map to labels defined in the application's
manifest. For example, player_experience and
com.google.test.loops.player_experience add all of the loops labeled in the
manifest with the com.google.test.loops.player_experience name to the
execution.
Scenarios can also be specified in the scenarios field.

=back

=head2 Google::Devtools::Testing::V1::TestExecution::IosXcTest

A test of an iOS application that uses the XCTest framework.
Xcode supports the option to "build for testing", which generates an
.xctestrun file that contains a test specification (arguments, test methods,
etc). This test type accepts a zip file containing the .xctestrun file and
the corresponding contents of the Build/Products directory that contains all
the binaries needed to run the tests.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->tests_zip() >> / C<< $msg->tests_zip($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::FileReference>)

Required. The .zip containing the .xctestrun file and the contents of the
DerivedData/Build/Products directory.
The .xctestrun file in this zip is ignored if the xctestrun field is
specified.

=item * C<< $msg->xctestrun() >> / C<< $msg->xctestrun($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::FileReference>)

An .xctestrun file that will override the .xctestrun file in the
tests zip. Because the .xctestrun file contains environment variables along
with test methods to run and/or ignore, this can be useful for sharding
tests. Default is taken from the tests zip.

=item * C<< $msg->xcode_version() >> / C<< $msg->xcode_version($value) >>

Type: C<String>

The Xcode version that should be used for the test.
Use the TestEnvironmentDiscoveryService to get supported options.
Defaults to the latest Xcode version Firebase Test Lab supports.

=item * C<< $msg->app_bundle_id() >> / C<< $msg->app_bundle_id($value) >>

Type: C<String>

Output only. The bundle id for the application under test.

=item * C<< $msg->test_special_entitlements() >> / C<< $msg->test_special_entitlements($value) >>

Type: C<Bool>

The option to test special app entitlements. Setting this would re-sign the
app having special entitlements with an explicit application-identifier.
Currently supports testing aps-environment entitlement.

=back

=head2 Google::Devtools::Testing::V1::TestExecution::IosTestLoop

A test of an iOS application that implements one or more game loop scenarios.
This test type accepts an archived application (.ipa file) and a list of
integer scenarios that will be executed on the app sequentially.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->app_ipa() >> / C<< $msg->app_ipa($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::FileReference>)

Required. The .ipa of the application to test.

=item * C<< $msg->scenarios() >> / C<< $msg->scenarios($value) >>

Type: C<Int32>

The list of scenarios that should be run during the test. Defaults to the
single scenario 0 if unspecified.

=item * C<< $msg->app_bundle_id() >> / C<< $msg->app_bundle_id($value) >>

Type: C<String>

Output only. The bundle id for the application under test.

=back

=head2 Google::Devtools::Testing::V1::TestExecution::IosRoboTest

A test that explores an iOS application on an iOS device.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->app_ipa() >> / C<< $msg->app_ipa($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::FileReference>)

Required. The ipa stored at this file should be used to run the test.

=item * C<< $msg->app_bundle_id() >> / C<< $msg->app_bundle_id($value) >>

Type: C<String>

The bundle ID for the app-under-test.
This is determined by examining the application's "Info.plist" file.

=item * C<< $msg->robo_script() >> / C<< $msg->robo_script($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::FileReference>)

An optional Roboscript to customize the crawl. See
https://firebase.google.com/docs/test-lab/android/robo-scripts-reference
for more information about Roboscripts.
The maximum allowed file size of the roboscript is 10MiB.

=back

=head2 Google::Devtools::Testing::V1::TestExecution::AndroidInstrumentationTest

A test of an Android application that can control an Android component
independently of its normal lifecycle.
Android instrumentation tests run an application APK and test APK inside the
same process on a virtual or physical AndroidDevice.  They also specify
a test runner class, such as com.google.GoogleTestRunner, which can vary
on the specific instrumentation framework chosen.

See <https://developer.android.com/training/testing/fundamentals> for
more information on types of Android tests.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->app_apk() >> / C<< $msg->app_apk($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::FileReference>)

The APK for the application under test.

=item * C<< $msg->app_bundle() >> / C<< $msg->app_bundle($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::AppBundle>)

A multi-apk app bundle for the application under test.

=item * C<< $msg->test_apk() >> / C<< $msg->test_apk($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::FileReference>)

Required. The APK containing the test code to be executed.

=item * C<< $msg->app_package_id() >> / C<< $msg->app_package_id($value) >>

Type: C<String>

The java package for the application under test.
The default value is determined by examining the application's manifest.

=item * C<< $msg->test_package_id() >> / C<< $msg->test_package_id($value) >>

Type: C<String>

The java package for the test to be executed.
The default value is determined by examining the application's manifest.

=item * C<< $msg->test_runner_class() >> / C<< $msg->test_runner_class($value) >>

Type: C<String>

The InstrumentationTestRunner class.
The default value is determined by examining the application's manifest.

=item * C<< $msg->test_targets() >> / C<< $msg->test_targets($value) >>

Type: C<String>

Each target must be fully qualified with the package name or class name,
in one of these formats:

 - "package package_name"
 - "class package_name.class_name"
 - "class package_name.class_name#method_name"

If empty, all targets in the module will be run.

=item * C<< $msg->orchestrator_option() >> / C<< $msg->orchestrator_option($value) >>

Type: C<Enum> (L<Google::Devtools::Testing::V1::OrchestratorOption>)

The option of whether running each test within its own invocation of
instrumentation with Android Test Orchestrator or not.
** Orchestrator is only compatible with AndroidJUnitRunner version 1.1 or
higher! **
Orchestrator offers the following benefits:

 - No shared state
 - Crashes are isolated
 - Logs are scoped per test

See
<https://developer.android.com/training/testing/junit-runner.html#using-android-test-orchestrator>
for more information about Android Test Orchestrator.

If not set, the test will be run without the orchestrator.

=item * C<< $msg->sharding_option() >> / C<< $msg->sharding_option($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::ShardingOption>)

The option to run tests in multiple shards in parallel.

=back

=head2 Google::Devtools::Testing::V1::TestExecution::AndroidRoboTest

A test of an android application that explores the application on a virtual
or physical Android Device, finding culprits and crashes as it goes.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->app_apk() >> / C<< $msg->app_apk($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::FileReference>)

The APK for the application under test.

=item * C<< $msg->app_bundle() >> / C<< $msg->app_bundle($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::AppBundle>)

A multi-apk app bundle for the application under test.

=item * C<< $msg->app_package_id() >> / C<< $msg->app_package_id($value) >>

Type: C<String>

The java package for the application under test.
The default value is determined by examining the application's manifest.

=item * C<< $msg->app_initial_activity() >> / C<< $msg->app_initial_activity($value) >>

Type: C<String>

The initial activity that should be used to start the app.

=item * C<< $msg->max_depth() >> / C<< $msg->max_depth($value) >>

Type: C<Int32>

The max depth of the traversal stack Robo can explore. Needs to be at least
2 to make Robo explore the app beyond the first activity.
Default is 50.

=item * C<< $msg->max_steps() >> / C<< $msg->max_steps($value) >>

Type: C<Int32>

The max number of steps Robo can execute.
Default is no limit.

=item * C<< $msg->robo_directives() >> / C<< $msg->robo_directives($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::RoboDirective>)

A set of directives Robo should apply during the crawl.
This allows users to customize the crawl. For example, the username and
password for a test account can be provided.

=item * C<< $msg->robo_mode() >> / C<< $msg->robo_mode($value) >>

Type: C<Enum> (L<Google::Devtools::Testing::V1::RoboMode>)

The mode in which Robo should run. Most clients should allow the server to
populate this field automatically.

=item * C<< $msg->robo_script() >> / C<< $msg->robo_script($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::FileReference>)

A JSON file with a sequence of actions Robo should perform as a prologue
for the crawl.

=item * C<< $msg->starting_intents() >> / C<< $msg->starting_intents($value) >>

Type: C<Message> (L<Google::Devtools::Testing::V1::TestExecution::RoboStartingIntent>)

The intents used to launch the app for the crawl.
If none are provided, then the main launcher activity is launched.
If some are provided, then only those provided are launched (the main
launcher activity must be provided explicitly).

=back

=head2 Google::Devtools::Testing::V1::TestExecution::RoboDirective

Directs Robo to interact with a specific UI element if it is encountered
